<?php namespace Workspace; $pid=$project; ?>
<section class="panel"><h2>Редакторский выпуск</h2><p>Book → Engine или Lite → Forum. Каждый этап подтверждается отдельно. Ошибка Forum не отменяет публикацию CMS.</p><form method="get"><input type="hidden" name="p" value="editorial"><label>Проект<select name="project" required><?php selectOptions($projects,$pid) ?></select></label><button>Открыть</button></form></section>
<?php if($pid!==null): ?>
<section class="panel"><h2>История маршрутов</h2><ul><?php foreach($runs as $r): ?><li><a href="<?= h(url('editorial',['project'=>$pid,'id'=>$r['id']])) ?>">#<?= (int)$r['id'] ?> · <?= h($r['tag']) ?> · <?= h($r['page_key']) ?></a> · <?= $r['abandoned_at']!==null?'закрыт':($r['cms_url']!==null?'CMS подтверждена':'CMS не подтверждена') ?></li><?php endforeach ?></ul><p><a href="<?= h(url('editorial',['project'=>$pid])) ?>">Новый маршрут</a></p></section>
<?php if($run): $rid=(int)$run['id'];$own=(int)$run['actor_id']===(int)$user['id']&&$run['abandoned_at']===null; ?>
<section class="panel"><h2>Маршрут #<?= $rid ?></h2><p><a href="<?= h(url('releases',['project'=>$pid,'id'=>$run['release_id']])) ?>">Выпуск продукта</a> · <a href="<?= h(url('book',['project'=>$pid,'edition'=>$run['edition_id']])) ?>">Зафиксированная редакция Book</a> · <a href="<?= h(url('forum',['project'=>$pid,'kind'=>'release','target'=>$run['release_id']])) ?>">Обсуждения (ACL Forum)</a></p><p>Страница: <?= h($run['page_key']) ?> · SHA-256 <code><?= h($run['page_hash']) ?></code></p><h3>1. Book — закреплено</h3><p>SHA-256 подборки: <code><?= h($run['snapshot_hash']) ?></code></p><h3>2. CMS — <?= h($cms['state']) ?></h3>
<?php if($run['engine_publication_id']!==null): ?><p><a href="<?= h(url('engine',['project'=>$pid,'publication'=>$run['engine_publication_id']])) ?>">Нативная публикация Engine</a></p><?php else: ?><p><a href="<?= h(url('lite',['project'=>$pid,'site'=>$run['lite_site_id']])) ?>">Нативная публикация Lite</a></p><?php if($cms['state']==='queued'): ?><p>Оператор: <code>php bin/workspace lite:work <?= (int)$cms['id'] ?></code></p><?php elseif(in_array($cms['state'],['running','uncertain'],true)): ?><p>Оператор: <code>php bin/workspace lite:reconcile <?= (int)$cms['id'] ?></code></p><?php endif ?><?php endif ?>
<?php if($run['cms_url']!==null): ?><p>Историческая ссылка: <a rel="noreferrer" href="<?= h($run['cms_url']) ?>"><?= h($run['cms_url']) ?></a> · <?= h(gmdate('Y-m-d H:i:s',(int)$run['cms_confirmed_at'])) ?> UTC. Это доказательство публикации, не гарантия текущего содержимого.</p><?php endif ?>
<?php if($own): ?><form method="post"><?php formFields('editorial.cms') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= $rid ?>"><label><input type="checkbox" name="confirm" value="yes" required> Подтверждаю публикацию или сверку CMS.</label><button class="primary">Выполнить / сверить этап CMS (MFA)</button></form><?php endif ?>
<?php if($run['abandoned_at']!==null): ?><p>Маршрут закрыт; история сохранена.</p><?php elseif(($own||$user['role']==='owner')&&$run['cms_url']===null&&(in_array($cms['state'],['conflict','cancelled','aborted'],true)||($run['lite_site_id']!==null&&$cms['id']===null))): ?><form method="post"><?php formFields('editorial.abandon') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= $rid ?>"><label><input type="checkbox" name="confirm" value="yes" required> Закрыть маршрут без публикации, сохранив историю и закреплённую редакцию Book.</label><button>Закрыть маршрут (MFA)</button></form><?php endif ?>
<h3>3. Forum — <?= h($discussion??'недоступно / права не подтверждены') ?></h3><?php if($verified): ?><p>Соответствие первого сообщения подтверждено текущим чтением Forum с личным токеном.</p><?php endif ?>
<?php if($own&&$forumAllowed&&$cms['url']!==null&&$run['cms_url']===$cms['url']): ?><p>В тему будут переданы тег выпуска и публичный адрес CMS. Убедитесь, что выбранный раздел подходит для этих сведений.</p><?php if(in_array($discussion,['sending','uncertain'],true)): ?><p>При неопределённом результате проверьте Forum и привяжите найденную тему штатным действием Forum. Повторная отправка запрещена.</p><?php endif ?><form method="post"><?php formFields($discussion==='rejected'?'editorial.retry':'editorial.forum') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= $rid ?>"><input type="hidden" name="attempt_key" value="<?= h($run['forum_key']) ?>"><label><input type="checkbox" name="confirm" value="yes" required> Подтверждаю создание или сверку обсуждения.</label><button class="primary"><?= $discussion==='rejected'?'Повторить только Forum':'Выполнить / сверить только Forum' ?> (MFA)</button></form><?php endif ?>
<?php if($own&&$forumAllowed&&$discussion==='uncertain'): ?><form method="post"><?php formFields('editorial.recover') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= $rid ?>"><input type="hidden" name="attempt_key" value="<?= h($run['forum_key']) ?>"><label>UUID найденной темы Forum<input name="thread_id" required maxlength="36"></label><label><input type="checkbox" name="confirm" value="yes" required> Проверить первое сообщение и восстановить связь без повторной отправки.</label><button>Восстановить связь (MFA)</button></form><?php endif ?>
<h3>Версии возможностей адаптеров</h3><ul><?php foreach($profiles as $profile): ?><li><?= h($profile['kind'].' '.$profile['version'].' · '.$profile['profile'].' · '.implode(', ',$profile['capabilities'])) ?></li><?php endforeach ?></ul><p>Engine и Book — совместимость по настройке и проверяемым ответам API; Lite — версия/schema при исполнении CLI; Forum — live health и личный ACL. Это не автоматическое обнаружение новых версий.</p>
<h3>Сравнение редакций</h3><form method="get"><input type="hidden" name="p" value="editorial"><input type="hidden" name="project" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= $rid ?>"><label>Источник<select name="compare"><option value="book">Book</option><option value="cms">Engine / Lite</option><?php if($forumAllowed&&$discussion==='linked'): ?><option value="forum">Forum</option><?php endif ?></select></label><label>Для Book: ID другой редакции этой книги (пусто — текущий Reader)<input name="previous" inputmode="numeric" maxlength="10"></label><button>Сравнить без изменений</button></form>
<?php if($run['lite_site_id']!==null&&$cms['state']==='published'): ?><p>Перед новым объявлением Forum и для сравнения Lite нужен свежий снимок (до 15 минут): <code>php bin/workspace lite:inspect <?= (int)$run['lite_site_id'] ?> OWNER_ID</code>. Сверяется точный SHA опубликованного состояния.</p><?php endif ?>
<?php if($comparisonError): ?><p class="planning-warning"><?= h($comparisonError) ?></p><?php endif ?>
<?php if($comparison): ?><h4><?= h($comparison['label']) ?> · <?= $comparison['equal']?'совпадает':'изменено' ?></h4><p>До: <code><?= h($comparison['before_hash']) ?></code><br>После: <code><?= h($comparison['after_hash']) ?></code></p><?php foreach($comparison['fields'] as $name=>$diff): ?><details <?= $diff['equal']?'':'open' ?>><summary><?= h($name) ?> · <?= $diff['equal']?'без изменений':'изменённый диапазон с строки '.$diff['first_line'].' (до '.$diff['removed'].', после '.$diff['added'].')' ?></summary><?php if(!$diff['equal']): ?><p>До</p><pre class="release-text"><?= h($diff['before']) ?></pre><p>После</p><pre class="release-text"><?= h($diff['after']) ?></pre><?php if($diff['bounded']): ?><p>Предпросмотр ограничен 80 строками / 16 000 байт на сторону. Хеши учитывают весь материал.</p><?php endif ?><?php endif ?></details><?php endforeach ?><?php endif ?>
<h3>История шагов</h3><div class="tablewrap"><table><thead><tr><th>UTC</th><th>Шаг</th><th>Состояние</th><th>Детали</th><th>Автор</th></tr></thead><tbody><?php foreach($events as $e): ?><tr><td><?= h(gmdate('Y-m-d H:i:s',(int)$e['created_at'])) ?></td><td><?= h($e['step']) ?></td><td><?= h($e['state']) ?></td><td><?= h($e['detail']) ?></td><td>#<?= (int)$e['actor_id'] ?></td></tr><?php endforeach ?></tbody></table></div><p>Последние 100 наблюдений. Нативные журналы содержат отдельные попытки и подтверждения.</p></section>
<?php else: ?>
<section class="panel"><h2>Новый маршрут</h2><p>Подготовьте согласованную текстовую страницу Book, подтверждённый релиз, целевой раздел Forum и черновик Engine либо свежий снимок Lite. Создание закрепляет Book за релизом, но ничего не публикует.</p><?php if(!$editions||!$releases||!$forum||(!$engine&&!$lite)): ?><p>Нет всех необходимых компонентов. <a href="<?= h(url('book',['project'=>$pid])) ?>">Book</a> · <a href="<?= h(url('releases',['project'=>$pid])) ?>">Релизы</a> · <a href="<?= h(url('forum',['project'=>$pid])) ?>">Forum</a> · <a href="<?= h(url('engine',['project'=>$pid])) ?>">Engine</a> · <a href="<?= h(url('lite',['project'=>$pid])) ?>">Lite</a></p><?php else: foreach(['engine'=>$engine,'lite'=>$lite] as $kind=>$targets): if(!$targets)continue; ?>
<h3><?= h($kind==='engine'?'CajeerEngine':'CajeerEngineLite') ?></h3><form method="post"><?php formFields('editorial.create') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="cms" value="<?= h($kind) ?>"><label>Согласованная страница<select name="page_choice" required><?php selectOptions($editions) ?></select></label><label>Подтверждённый выпуск<select name="release_id" required><?php foreach($releases as $r): ?><option value="<?= (int)$r['id'] ?>" <?= (string)$r['id']===(string)($_GET['release']??'')?'selected':'' ?>><?= h($r['tag']) ?></option><?php endforeach ?></select></label><label>Привязка раздела Forum (ID из раздела Forum)<select name="forum_source_id" required><?php foreach($forum as $f): ?><option value="<?= (int)$f['id'] ?>">#<?= (int)$f['id'] ?></option><?php endforeach ?></select></label>
<?php if($kind==='engine'): ?><label>Подготовленный черновик<select name="engine_publication_id" required><?php foreach($targets as $t): ?><option value="<?= (int)$t['id'] ?>">#<?= (int)$t['id'] ?> · <?= h($t['name'].' / '.$t['content_type'].' / '.$t['entry_id'].' v'.$t['revision']) ?></option><?php endforeach ?></select></label><label>Поле текста Engine<input name="engine_field" value="body" maxlength="128" required></label><p>Заголовок и выбранное поле должны точно совпадать с Book.</p><?php else: ?><label>Сайт и снимок<select name="lite_target" required><?php foreach($targets as $t): ?><option value="<?= h($t['id'].':'.$t['site_hash']) ?>"><?= h($t['name'].' · '.substr($t['site_hash'],0,12)) ?></option><?php endforeach ?></select></label><label>Новый путь<input name="lite_path" placeholder="/release-notes" maxlength="1024" required></label><?php endif ?><button class="primary">Закрепить маршрут (MFA)</button></form><?php endforeach; endif ?></section><?php endif; endif ?>
